import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-Category-Label-Positions.md","filePath":"manual-zh/CTABLES-Category-Label-Positions.md","lastUpdated":1785684581000}'),a={name:"manual-zh/CTABLES-Category-Label-Positions.md"};function l(h,t,n,i,L,c){return e(),r("div",null,[...t[0]||(t[0]=[o(`<h4 id="_15-7-4-类别标签位置" tabindex="-1">15.7.4 类别标签位置 <a class="header-anchor" href="#_15-7-4-类别标签位置" aria-label="Permalink to &quot;15.7.4 类别标签位置&quot;">​</a></h4><pre><code>/CLABELS {AUTO _|_ {ROWLABELS _|_ COLLABELS}={OPPOSITE _|_ LAYER}}
</code></pre><p><code>CLABELS</code> 子命令控制其后面的 <code>TABLE</code> 子命令的类别标签位置。默认情况下，或指定 <code>AUTO</code> 时，给定变量的类别标签嵌套在同一轴上该变量的标签内。例如，以下命令会使年龄类别嵌套在行轴上的年龄组变量内，性别类别嵌套在列轴上的性别变量内：</p><pre><code>CTABLES /TABLE ageGroup BY gender.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Male</th><th>Female</th></tr></thead><tbody><tr><td></td><td></td><td>S3a. GENDER:</td><td></td></tr><tr><td></td><td></td><td>Count</td><td>Count</td></tr><tr><td>Age group</td><td>15 or younger</td><td>0</td><td>0</td></tr><tr><td>16 to 25</td><td>594</td><td>505</td><td></td></tr><tr><td>26 to 35</td><td>476</td><td>491</td><td></td></tr><tr><td>36 to 45</td><td>489</td><td>548</td><td></td></tr><tr><td>46 to 55</td><td>526</td><td>649</td><td></td></tr><tr><td>56 to 65</td><td>516</td><td>731</td><td></td></tr><tr><td>66 or older</td><td>531</td><td>943</td><td></td></tr></tbody></table><p><code>ROWLABELS=OPPOSITE</code> 或 <code>COLLABELS=OPPOSITE</code> 分别将行变量或列变量的类别标签移到相反的轴。该设置只影响给定轴上最内层的变量（这些变量必须是分类变量）。例如：</p><pre><code>CTABLES /TABLE ageGroup BY gender /CLABELS ROWLABELS=OPPOSITE.
CTABLES /TABLE ageGroup BY gender /CLABELS COLLABELS=OPPOSITE.
</code></pre><table tabindex="0"><thead><tr><th></th><th>15 or younger</th><th>16 to 25</th><th>26 to 35</th><th>36 to 45</th><th>46 to 55</th><th>56 to 65</th><th>66 or older</th><th>15 or younger</th><th>16 to 25</th><th>26 to 35</th><th>36 to 45</th><th>46 to 55</th><th>56 to 65</th><th>66 or older</th></tr></thead><tbody><tr><td></td><td>S3a. GENDER:</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>Male</td><td>Female</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td></tr><tr><td>Age group</td><td>0</td><td>594</td><td>476</td><td>489</td><td>526</td><td>516</td><td>531</td><td>0</td><td>505</td><td>491</td><td>548</td><td>649</td><td>731</td><td>943</td></tr><tr><td></td><td></td><td></td><td>S3a. GENDER:</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td>Count</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Age group</td><td>15 or younger</td><td>Male</td><td>0</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>0</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>16 to 25</td><td>Male</td><td>594</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>505</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>26 to 35</td><td>Male</td><td>476</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>491</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>36 to 45</td><td>Male</td><td>489</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>548</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>46 to 55</td><td>Male</td><td>526</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>649</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>56 to 65</td><td>Male</td><td>516</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>731</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>66 or older</td><td>Male</td><td>531</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>943</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><code>ROWLABELS=LAYER</code> 或 <code>COLLABELS=LAYER</code> 分别将最内层的行变量或列变量的类别标签移到层轴。</p><p>只能移动一个轴的标签，无论是移到相反的轴还是层轴。</p><h4 id="对汇总统计量的影响" tabindex="-1">对汇总统计量的影响 <a class="header-anchor" href="#对汇总统计量的影响" aria-label="Permalink to &quot;对汇总统计量的影响&quot;">​</a></h4><p><code>CLABELS</code> 主要影响表的外观，而不影响其中显示的数据。然而，<code>CTABLES</code> 可能影响用于汇总表区域的统计量所显示的值，因为它会改变这些区域的定义。</p><p>例如，考虑以下语法和输出：</p><pre><code>CTABLES /TABLE ageGroup BY gender [ROWPCT, COLPCT].
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Row %</th><th>Column %</th><th>Row %</th><th>Column %</th></tr></thead><tbody><tr><td></td><td></td><td>S3a. GENDER:</td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>Male</td><td>Female</td><td></td><td></td></tr><tr><td>Age group</td><td>15 or younger</td><td>.</td><td>.0%</td><td>.</td><td>.0%</td></tr><tr><td>16 to 25</td><td>54.0%</td><td>19.0%</td><td>46.0%</td><td>13.1%</td><td></td></tr><tr><td>26 to 35</td><td>49.2%</td><td>15.2%</td><td>50.8%</td><td>12.7%</td><td></td></tr><tr><td>36 to 45</td><td>47.2%</td><td>15.6%</td><td>52.8%</td><td>14.2%</td><td></td></tr><tr><td>46 to 55</td><td>44.8%</td><td>16.8%</td><td>55.2%</td><td>16.8%</td><td></td></tr><tr><td>56 to 65</td><td>41.4%</td><td>16.5%</td><td>58.6%</td><td>18.9%</td><td></td></tr><tr><td>66 or older</td><td>36.0%</td><td>17.0%</td><td>64.0%</td><td>24.4%</td><td></td></tr></tbody></table><p>使用 <code>COLLABELS=OPPOSITE</code> 会改变行和列的定义，使得列百分比显示的是之前的行百分比，而新的行百分比变得没有意义（因为每行只有一个单元格）：</p><pre><code>CTABLES
    /TABLE ageGroup BY gender [ROWPCT, COLPCT]
    /CLABELS COLLABELS=OPPOSITE.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>Row %</th><th>Column %</th></tr></thead><tbody><tr><td></td><td></td><td></td><td>S3a. GENDER:</td><td></td></tr><tr><td>Age group</td><td>15 or younger</td><td>Male</td><td>.</td><td>.</td></tr><tr><td>Female</td><td>.</td><td>.</td><td></td><td></td></tr><tr><td>16 to 25</td><td>Male</td><td>100.0%</td><td>54.0%</td><td></td></tr><tr><td>Female</td><td>100.0%</td><td>46.0%</td><td></td><td></td></tr><tr><td>26 to 35</td><td>Male</td><td>100.0%</td><td>49.2%</td><td></td></tr><tr><td>Female</td><td>100.0%</td><td>50.8%</td><td></td><td></td></tr><tr><td>36 to 45</td><td>Male</td><td>100.0%</td><td>47.2%</td><td></td></tr><tr><td>Female</td><td>100.0%</td><td>52.8%</td><td></td><td></td></tr><tr><td>46 to 55</td><td>Male</td><td>100.0%</td><td>44.8%</td><td></td></tr><tr><td>Female</td><td>100.0%</td><td>55.2%</td><td></td><td></td></tr><tr><td>56 to 65</td><td>Male</td><td>100.0%</td><td>41.4%</td><td></td></tr><tr><td>Female</td><td>100.0%</td><td>58.6%</td><td></td><td></td></tr><tr><td>66 or older</td><td>Male</td><td>100.0%</td><td>36.0%</td><td></td></tr><tr><td>Female</td><td>100.0%</td><td>64.0%</td><td></td><td></td></tr></tbody></table><h4 id="为堆叠变量移动类别" tabindex="-1">为堆叠变量移动类别 <a class="header-anchor" href="#为堆叠变量移动类别" aria-label="Permalink to &quot;为堆叠变量移动类别&quot;">​</a></h4><p>如果 <code>CLABELS</code> 从带有堆叠变量的轴移动类别标签，则被移动的变量必须具有相同的类别规范（参见 <a href="./CTABLES-Per_002dVariable-Category-Options">CTABLES Per-Variable Category Options</a>）和相同的值标签。</p><p>以下展示了既移动堆叠类别变量，又适应行和列定义的变化：</p><pre><code>CTABLES /TABLE (likelihoodOfBeingStoppedByPolice
                + likelihoodOfHavingAnAccident) [COLPCT].
CTABLES /TABLE (likelihoodOfBeingStoppedByPolice
                + likelihoodOfHavingAnAccident) [ROWPCT]
  /CLABELS ROW=OPPOSITE.
</code></pre><table tabindex="0"><thead><tr><th></th><th>Almost certain</th><th>Very likely</th><th>Somewhat likely</th><th>Somewhat unlikely</th><th>Very unlikely</th></tr></thead><tbody><tr><td></td><td></td><td>Column %</td><td></td><td></td><td></td></tr><tr><td>105b. How likely is it that drivers who have had too much to drink to drive safely will A. Get stopped by the police?</td><td>Almost certain</td><td>10.2%</td><td></td><td></td><td></td></tr><tr><td>Very likely</td><td>21.8%</td><td></td><td></td><td></td><td></td></tr><tr><td>Somewhat likely</td><td>40.2%</td><td></td><td></td><td></td><td></td></tr><tr><td>Somewhat unlikely</td><td>19.0%</td><td></td><td></td><td></td><td></td></tr><tr><td>Very unlikely</td><td>8.9%</td><td></td><td></td><td></td><td></td></tr><tr><td>105b. How likely is it that drivers who have had too much to drink to drive safely will B. Have an accident?</td><td>Almost certain</td><td>15.9%</td><td></td><td></td><td></td></tr><tr><td>Very likely</td><td>40.8%</td><td></td><td></td><td></td><td></td></tr><tr><td>Somewhat likely</td><td>35.0%</td><td></td><td></td><td></td><td></td></tr><tr><td>Somewhat unlikely</td><td>6.2%</td><td></td><td></td><td></td><td></td></tr><tr><td>Very unlikely</td><td>2.0%</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>Row %</td><td>Row %</td><td>Row %</td><td>Row %</td><td>Row %</td></tr><tr><td>105b. How likely is it that drivers who have had too much to drink to drive safely will A. Get stopped by the police?</td><td>10.2%</td><td>21.8%</td><td>40.2%</td><td>19.0%</td><td>8.9%</td></tr><tr><td>105b. How likely is it that drivers who have had too much to drink to drive safely will B. Have an accident?</td><td>15.9%</td><td>40.8%</td><td>35.0%</td><td>6.2%</td><td>2.0%</td></tr></tbody></table>`,23)])])}const E=d(a,[["render",l]]);export{p as __pageData,E as default};
